def forward(groups):
    value = float(groups[0])
    unit = groups[1].lower()
    if unit == 'b':
        multiplier = 1
    elif unit == 'kb':
        multiplier = 1024
    elif unit == 'mb':
        multiplier = 1024 * 1024
    else:
        raise ValueError("Unknown unit")
    return {'stored': [int(value * multiplier)], 'layout': [groups[1]]}

def inverse(record):
    value = record['stored'][0]
    unit = record['layout'][0]
    if unit.lower() == 'kb':
        display_value = value / 1024
    elif unit.lower() == 'mb':
        display_value = value / (1024 * 1024)
    else:
        display_value = value
    return f'(size: {display_value:.1f} {unit})'
